  const bright = lat === 0 ? 0.25 : 1;
  return e('div', {key:'lt'+i, style:{position:'absolute', left:0, top:((90 - lat) / 180) * height, width:'100%', height: lat === 0 ? 1.5 : 1, backgroundColor: D.text_dim, opacity: gridAlpha * bright}});
});

